import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { TextReveal } from "./03-outcome-stories/text-reveal";
const VIEWPORT_HEAD = { once: true, margin: "-50px" } as const;
const VIEWPORT_CARD = { once: true, margin: "-60px" } as const;
const VIEWPORT_RING = { once: true, margin: "-80px" } as const;
const LINK_CLASS = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:gap-1.5 art:px-3 art:text-xs art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:mt-5 art:w-fit art:h-9 art:rounded-full";
interface OutcomeStory {
    id: string;
    articleClass: string;
    ringClass: string;
    glowClass: string;
    icon: ReactNode;
    eyebrow: string;
    title: string;
    body: string;
    outcome: string;
    link: string;
}
const ICON_PROPS = {
    xmlns: "http://www.w3.org/2000/svg",
    width: "24",
    height: "24",
    viewBox: "0 0 24 24",
