export default function UseCasesOutcomeStories() {
    const reduce = useReducedMotion();
    return (<section className="art:w-full art:overflow-hidden art:bg-background art:px-4 art:py-20 art:text-foreground art:@min-[640px]/artemis:px-6 art:@min-[640px]/artemis:py-24 art:@min-[1024px]/artemis:px-8 art:@min-[1024px]/artemis:py-28">
      <div className="art:mx-auto art:w-full art:max-w-7xl">
        <div className="art:mx-auto art:max-w-3xl art:text-center">
          <motion.span className="art:inline-flex art:rounded-full art:border art:border-border/70 art:bg-background art:px-3 art:py-1.5 art:font-medium art:text-muted-foreground art:text-xs" initial={{ opacity: 0, filter: "blur(5px)", y: 8 }} whileInView={reduce ? undefined : { opacity: 1, filter: "blur(0px)", y: 0 }} viewport={VIEWPORT_HEAD} transition={{ duration: 0.45, ease: ARTEMIS_EASE_OUT }}>
            Use cases
          </motion.span>
          <TextReveal as="h2" text={["Less friction around the work.", "More room for the work itself."]} className="art:mt-7 art:text-balance art:tracking-[-0.05em] art:text-4xl art:font-medium"/>
          <motion.p className="art:mx-auto art:mt-6 art:max-w-2xl art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:@min-[640px]/artemis:text-base art:@min-[640px]/artemis:leading-7" initial={{ opacity: 0, filter: "blur(6px)", y: 10 }} whileInView={reduce ? undefined : { opacity: 1, filter: "blur(0px)", y: 0 }} viewport={VIEWPORT_HEAD} transition={{ duration: 0.5, delay: 0.26, ease: ARTEMIS_EASE_OUT }}>
            Different teams arrive with different needs. Each story starts with the moment they want to make simpler and
            ends with an outcome people can feel.
          </motion.p>
        </div>
        <div className="art:mt-14 art:grid art:gap-4 art:@min-[768px]/artemis:grid-cols-3 art:@min-[640px]/artemis:mt-16 art:@min-[1024px]/artemis:gap-5">
          {STORIES.map((story, i) => (<motion.article key={story.id} className={`art:group art:flex art:min-w-0 art:flex-col art:overflow-hidden art:rounded-3xl art:border art:border-border/70 art:bg-background art:p-3${story.articleClass}`} initial={{ opacity: 0, filter: "blur(8px)", y: 18 }} whileInView={reduce ? undefined : { opacity: 1, filter: "blur(0px)", y: 0 }} viewport={VIEWPORT_CARD} transition={{ duration: 0.6, delay: i * 0.08, ease: ARTEMIS_EASE_OUT }}>
              <div className="art:relative art:h-52 art:overflow-hidden art:rounded-3xl art:bg-muted/55">
                <motion.div aria-hidden="true" className={`art:absolute art:rounded-full art:border art:border-border/60 art:bg-background/70 ${story.ringClass}`} initial={{ opacity: 0, scale: 0.88 }} whileInView={reduce ? undefined : { opacity: 1, scale: 1 }} viewport={VIEWPORT_RING} transition={{ duration: 0.7, ease: ARTEMIS_EASE_OUT }}/>
                <div aria-hidden="true" className={`art:absolute art:rounded-full art:bg-primary/8 art:blur-xl ${story.glowClass}`}/>
                <div className="art:absolute art:inset-0 art:grid art:place-items-center">
                  <span className="art:grid art:size-14 art:place-items-center art:rounded-full art:bg-background art:text-foreground">
                    {story.icon}
                  </span>
                </div>
              </div>
              <div className="art:flex art:flex-1 art:flex-col art:px-4 art:pt-6 art:pb-5 art:@min-[640px]/artemis:px-5 art:@min-[640px]/artemis:pb-6">
                <p className="art:font-medium art:text-muted-foreground art:text-xs">{story.eyebrow}</p>
                <h3 className="art:mt-3 art:text-pretty art:leading-[1.04] art:tracking-[-0.04em] art:text-xl art:font-medium">{story.title}</h3>
                <p className="art:mt-4 art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">{story.body}</p>
                <div className="art:mt-8 art:border-border/60 art:border-t art:pt-5">
                  <p className="art:font-medium art:text-base art:tracking-[-0.02em]">{story.outcome}</p>
                  <motion.a className={LINK_CLASS} href="#" tabIndex={0} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS}>
                    {story.link}
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-4" aria-hidden="true">
                      <path d="M7 7h10v10"/>
                      <path d="M7 17 17 7"/>
                    </svg>
                  </motion.a>
                </div>
              </div>
            </motion.article>))}
        </div>
      </div>
    </section>);
}

"use client";
// @zeus-internal
import { ArtemisWordEntrance } from "./word-entrance";
import type { ArtemisWordMotionOptions } from "./word-motion";
export interface ArtemisTextRevealProps extends ArtemisWordMotionOptions {
  text: string | string[];
  as?: "span" | "div" | "p" | "h1" | "h2" | "h3" | "h4";
  className?: string;
  once?: boolean;
  amount?: number;
  whileInView?: boolean;
}
export function ArtemisTextReveal({
  text,
  as: Tag = "span",
  className = "",
  stagger = 0.06,
  yOffset = "24%",
  delay = 0,
  whileInView = true,
  ...options
}: ArtemisTextRevealProps) {
  const lines = Array.isArray(text) ? text : [text];
  let offset = 0;
  return (
    <Tag className={`art:block ${className}`}>
      {lines.map((line, index) => {
        const words = line.split(/\s+/),
          start = offset;
        offset += words.length;
        return (
          <ArtemisWordEntrance
            key={index}
            words={words}
            stagger={stagger}
            delay={delay + start * stagger}
            yOffset={yOffset}
            entered={whileInView ? undefined : true}
            {...options}
          />
        );
      })}
    </Tag>
  );
}

"use client";
// @zeus-internal
import { motion, useInView, useReducedMotion } from "motion/react";
import { useRef } from "react";
import { artemisWordMotion, type ArtemisWordMotionOptions } from "./word-motion";
export interface ArtemisWordEntranceProps {
  words: string[];
  className?: string;
  stagger?: number;
  delay?: number;
  blur?: number;
  yOffset?: string | number;
  spring?: ArtemisWordMotionOptions["spring"];
  once?: boolean;
  amount?: number;
  entered?: boolean;
}
export function ArtemisWordEntrance({
  words,
  className = "",
  stagger = 0.055,
  delay = 0,
  blur = 10,
  yOffset = "20%",
  amount = 0.4,
  spring,
  once = true,
  entered: externalEntry,
}: ArtemisWordEntranceProps) {
  const element = useRef<HTMLSpanElement>(null);
  const observed = useInView(element, { once, amount });
  const entered = externalEntry ?? observed;
  const reduced = useReducedMotion() === true;
  return (
    <span ref={element} className={`art:block ${className}`}>
      <span className="art:block">
        {words.map((word, index) => {
          const movement = artemisWordMotion(index, reduced, {
            delay,
            stagger,
            blur,
            yOffset,
            spring,
          });
          return (
            <motion.span
              key={index}
              className="art:inline-block"
              initial={movement.initial}
              // With reduced motion the words land on mount instead of waiting to be seen.
              animate={entered || reduced ? movement.animate : undefined}
              transition={movement.transition}
            >
              {word}
              {index < words.length - 1 && (
                <span className="art:inline-block art:w-[0.25em] art:overflow-hidden">
                  {"\u00a0"}
                </span>
              )}
            </motion.span>
          );
        })}
      </span>
    </span>
  );
}

// @zeus-internal
import { ARTEMIS_EASE_OUT } from "./ease";
export interface ArtemisWordMotionOptions {
  delay?: number;
  stagger?: number;
  blur?: number;
  yOffset?: string | number;
  spring?: { stiffness?: number; damping?: number; mass?: number };
}
export function artemisWordMotion(
  index: number,
  reduced: boolean,
  { delay = 0, stagger = 0.055, blur = 10, yOffset = "20%", spring }: ArtemisWordMotionOptions = {}
) {
  const offset = delay + index * stagger;
  // The same start with reduced motion, so hydration matches the server; the words then land at once.
  return {
    initial: { opacity: 0, filter: `blur(${blur}px)`, y: yOffset },
    animate: { opacity: 1, filter: "blur(0px)", y: 0 },
    transition: reduced
      ? { duration: 0 }
      : {
          opacity: { duration: 0.7, delay: offset, ease: ARTEMIS_EASE_OUT },
          filter: { duration: 0.9, delay: offset, ease: ARTEMIS_EASE_OUT },
          y: {
            type: "spring" as const,
            stiffness: spring?.stiffness ?? 140,
            damping: spring?.damping ?? 26,
            mass: spring?.mass ?? 1.2,
            delay: offset,
          },
        },
  };
}
